Object.assign(SNIP,{"l41it": "vector<int> v = {4, 7, 1};\nvector<int>::iterator it = v.begin();   // hoặc: auto it = v.begin();\ncout << *it;                            // 4: giá trị tại vị trí it chỉ tới\n++it;                                   // sang phần tử kế tiếp\n*it = 70;                               // ghi qua iterator: v = {4, 70, 1}\nfor (auto p = v.begin(); p != v.end(); ++p)\n    cout << *p << \" \";                  // end() là vị trí SAU phần tử cuối: không dùng *v.end()", "l41erase": "auto moiCuoi = remove_if(v.begin(), v.end(), laAm);  // dồn phần giữ lại lên đầu, CHƯA xóa\nv.erase(moiCuoi, v.end());                           // xóa thật phần đuôi thừa", "l41alg": "sort(v.begin(), v.end());                 // cả dãy\nsort(v.begin() + 1, v.begin() + 4);       // chỉ v[1], v[2], v[3]: khoảng [first, last)\nauto it = find(v.begin(), v.end(), 8);    // không thấy thì trả về v.end()\nif (it != v.end()) cout << it - v.begin();  // vị trí (chỉ số) của phần tử tìm được\nint k = count_if(v.begin(), v.end(), laChan);   // laChan là một hàm bool laChan(int)"});PRESET_NOTES["l41"]={"Ví dụ: duyệt vector bằng iterator": "*it đọc và ghi phần tử tại vị trí it chỉ tới (giống con trỏ). Vòng for đi từ begin() tới khi p == end(): end() nằm sau phần tử cuối nên vòng lặp dừng đúng lúc. end() - begin() bằng số phần tử.", "Ví dụ: find, count, max_element": "find trả về iterator tới số 8 ĐẦU TIÊN; không thấy 4 thì trả về v.end() (it2 nằm sau ô cuối). max_element cũng trả về iterator chứ không phải giá trị: lấy giá trị bằng *lon, lấy chỉ số bằng distance hoặc lon - v.begin().", "Ví dụ: sort một đoạn [first, last)": "[v.begin() + 1, v.begin() + 4) gồm v[1], v[2], v[3] (không gồm v[4]): chỉ 4, 7, 1 được sắp lại thành 1, 4, 7. Ô vừa ghi tô cam cho thấy thuật toán đã đụng tới những ô nào.", "Ví dụ: count_if, find_if với hàm điều kiện": "Bấm Từng bước: count_if gọi laChan(3), laChan(12)… lần lượt với cả 6 phần tử. find_if dừng ngay ở phần tử đầu tiên thỏa điều kiện (12), không gọi tiếp. all_of dừng ngay khi gặp phần tử đầu tiên KHÔNG thỏa (3).", "Ví dụ: remove_if rồi erase": "remove_if dồn 4, 7, 3 lên đầu và trả về moiCuoi chỉ vào ô ngay sau chúng; ba ô cuối vẫn còn (giá trị cũ), size vẫn là 6. erase(moiCuoi, v.end()) mới thật sự xóa phần đuôi.", "Ví dụ: transform, copy, back_inserter": "b đang rỗng: back_inserter(b) biến mỗi lần “ghi” thành b.push_back(...), nên b lớn dần. c đã có sẵn 3 ô nên copy ghi thẳng vào c.begin(). Nếu c rỗng mà vẫn copy vào c.begin() thì ghi ra ngoài vùng nhớ.", "Ví dụ: lower_bound trên dãy đã sắp xếp": "lower_bound(x): phần tử đầu tiên ≥ x; upper_bound(x): phần tử đầu tiên > x. Các số bằng x nằm trọn trong [dau, cuoi), nên cuoi - dau là số lần xuất hiện. Cả ba hàm chia đôi dãy (O(log n)) nên dãy PHẢI được sắp xếp trước.", "Ví dụ: iterator ngược, iterator của set và map": "rbegin() chỉ vào phần tử cuối, ++ lùi dần về đầu. Cùng một kiểu vòng lặp (begin, end, ++, *) duyệt được vector, set (tăng dần) và map (theo khóa); với map, it->first là khóa, it->second là giá trị.", "Lỗi: dùng *it khi không tìm thấy": "Không có 7 nên it == v.end(): ở đó không có phần tử nào. *v.end() là hành vi không xác định: máy thật có thể in một số rác (thường là 0) hoặc dừng; trình mô phỏng dừng và báo lỗi. Luôn kiểm tra if (it != v.end()) trước.", "Lỗi: in iterator thay vì giá trị": "it là một vị trí, cout không in được iterator. Muốn in phần tử: cout << *it; muốn in chỉ số: cout << it - v.begin();"};EX_HINTS["l41"]=[["Số âm chẵn (−2) cũng là số chẵn: x % 2 == 0 vẫn đúng với số âm.", "find_if trả về v.end() khi không có; chỉ số là it - v.begin()."], ["remove_if trả về iterator tới cuối mới; erase từ đó tới v.end().", "0 không phải số âm nên được giữ lại."], ["Các phần tử trong [l, r] nằm liền nhau trong dãy đã sắp: từ phần tử đầu tiên ≥ l tới trước phần tử đầu tiên > r.", "Hiệu hai iterator là số phần tử giữa chúng."]];
/* ===================== BÀI 41 · Iterator và algorithm ===================== */
/* Bài 41 · Iterator và algorithm
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const P41=[{label:"Ví dụ: duyệt vector bằng iterator",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {4, 7, 1, 9, 3};\n    vector<int>::iterator it = v.begin();\n    cout << *it << \"\\n\";\n    ++it;\n    *it = 70;\n    for (auto p = v.begin(); p != v.end(); ++p) {\n        cout << *p << \" \";\n    }\n    cout << \"\\n\";\n    cout << \"So phan tu: \" << v.end() - v.begin() << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"v",ptr:["it","p"]}]},{label:"Ví dụ: find, count, max_element",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    vector<int> v = {5, 8, 2, 8, 6};\n    auto it = find(v.begin(), v.end(), 8);\n    if (it != v.end()) {\n        cout << \"Tim thay 8 o vi tri \" << it - v.begin() << \"\\n\";\n    }\n    auto it2 = find(v.begin(), v.end(), 4);\n    if (it2 == v.end()) {\n        cout << \"Khong co 4\\n\";\n    }\n    cout << \"So lan 8: \" << count(v.begin(), v.end(), 8) << \"\\n\";\n    auto lon = max_element(v.begin(), v.end());\n    cout << \"Lon nhat \" << *lon << \" o vi tri \" << distance(v.begin(), lon) << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"v",ptr:["it","it2","lon"]}]},{label:"Ví dụ: sort một đoạn [first, last)",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    vector<int> v = {9, 4, 7, 1, 8, 2};\n    sort(v.begin() + 1, v.begin() + 4);\n    for (int x : v) cout << x << \" \";\n    cout << \"\\n\";\n    reverse(v.begin(), v.end());\n    for (int x : v) cout << x << \" \";\n    cout << \"\\n\";\n    sort(v.begin(), v.end());\n    for (int x : v) cout << x << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"v",ptr:[]}]},{label:"Ví dụ: count_if, find_if với hàm điều kiện",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nbool laChan(int x) {\n    return x % 2 == 0;\n}\nbool lonHon10(int x) {\n    return x > 10;\n}\nint main() {\n    vector<int> v = {3, 12, 7, 8, 15, 4};\n    cout << \"So chan: \" << count_if(v.begin(), v.end(), laChan) << \"\\n\";\n    auto it = find_if(v.begin(), v.end(), lonHon10);\n    cout << \"So dau tien > 10: \" << *it << \"\\n\";\n    if (all_of(v.begin(), v.end(), laChan)) {\n        cout << \"Toan so chan\\n\";\n    } else {\n        cout << \"Co so le\\n\";\n    }\n    return 0;\n}",viz:[{type:"cells",of:"v",ptr:["it"]}]},{label:"Ví dụ: remove_if rồi erase",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nbool laAm(int x) {\n    return x < 0;\n}\nint main() {\n    vector<int> v = {4, -2, 7, -5, -1, 3};\n    auto moiCuoi = remove_if(v.begin(), v.end(), laAm);\n    cout << \"Sau remove_if, size van la \" << v.size() << \"\\n\";\n    v.erase(moiCuoi, v.end());\n    for (int x : v) cout << x << \" \";\n    cout << \"\\nsize = \" << v.size() << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"v",ptr:["moiCuoi"]}]},{label:"Ví dụ: transform, copy, back_inserter",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <iterator>\nusing namespace std;\n\nint binhPhuong(int x) {\n    return x * x;\n}\nint main() {\n    vector<int> a = {1, 2, 3, 4};\n    vector<int> b;\n    transform(a.begin(), a.end(), back_inserter(b), binhPhuong);\n    for (int x : b) cout << x << \" \";\n    cout << \"\\n\";\n    vector<int> c(3);\n    copy(a.begin(), a.begin() + 3, c.begin());\n    for (int x : c) cout << x << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"b",ptr:[]},{type:"cells",of:"c",ptr:[]}]},{label:"Ví dụ: lower_bound trên dãy đã sắp xếp",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <numeric>\nusing namespace std;\n\nint main() {\n    vector<int> v = {2, 4, 4, 4, 7, 9};\n    auto dau = lower_bound(v.begin(), v.end(), 4);\n    auto cuoi = upper_bound(v.begin(), v.end(), 4);\n    cout << \"So 4 xuat hien \" << cuoi - dau << \" lan\\n\";\n    cout << \"Co so 5? \" << binary_search(v.begin(), v.end(), 5) << \"\\n\";\n    auto p = lower_bound(v.begin(), v.end(), 5);\n    cout << \"So nho nhat >= 5: \" << *p << \"\\n\";\n    cout << \"Tong: \" << accumulate(v.begin(), v.end(), 0) << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"v",ptr:["dau","cuoi","p"]}]},{label:"Ví dụ: iterator ngược, iterator của set và map",input:"",code:"#include <iostream>\n#include <vector>\n#include <set>\n#include <map>\n#include <string>\nusing namespace std;\n\nint main() {\n    vector<int> v = {1, 2, 3, 4};\n    for (auto it = v.rbegin(); it != v.rend(); ++it) {\n        cout << *it << \" \";\n    }\n    cout << \"\\n\";\n    set<int> s = {7, 2, 9, 4};\n    for (auto it = s.begin(); it != s.end(); ++it) {\n        cout << *it << \" \";\n    }\n    cout << \"\\n\";\n    map<string, int> tuoi = {{\"An\", 20}, {\"Binh\", 19}};\n    for (auto it = tuoi.begin(); it != tuoi.end(); ++it) {\n        cout << it->first << \" \" << it->second << \"\\n\";\n    }\n    return 0;\n}",viz:[{type:"cells",of:"v",ptr:["it"]}]},{label:"Lỗi: dùng *it khi không tìm thấy",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    vector<int> v = {5, 1, 4};\n    auto it = find(v.begin(), v.end(), 7);\n    cout << *it << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"v",ptr:["it"]}]},{label:"Lỗi: in iterator thay vì giá trị",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {1, 2, 3};\n    auto it = v.begin();\n    cout << it << \"\\n\";\n    return 0;\n}"}];
