makeEx2(document.getElementById("ex-l41"),sim41,[{t:"Số chẵn và số âm đầu tiên",d:"Nhập n rồi n số nguyên. Dòng 1 in số lượng số chẵn. Dòng 2 in chỉ số (tính từ 0) của số âm đầu tiên, không có thì in <code>-1<\/code>. Dùng <code>count_if<\/code> và <code>find_if<\/code> với hai hàm điều kiện bạn tự viết.",tests:[{in:"6\n3 8 -2 5 -7 4",out:"3\n2"},{in:"3\n1 3 5",out:"0\n-1"},{in:"1\n-4",out:"1\n0"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\n// bool laChan(int x) { ... }\n// bool laAm(int x) { ... }\nint main() {\n    int n;\n    cin >> n;\n    vector<int> v(n);\n    for (int& x : v) cin >> x;\n    // count_if(...), find_if(...)\n    return 0;\n}",need:/count_if[\s\S]*find_if|find_if[\s\S]*count_if/,needMsg:"Hãy dùng count_if và find_if."},{t:"Lọc bỏ số âm rồi sắp xếp",d:"Nhập n rồi n số nguyên. Xóa mọi số âm khỏi vector bằng <code>remove_if<\/code> + <code>erase<\/code>, sắp xếp phần còn lại tăng dần rồi in ra trên một dòng (cách nhau một dấu cách). Dòng sau in <code>Con lai: k<\/code>.",tests:[{in:"6\n4 -2 7 -5 0 3",out:"0 3 4 7\nCon lai: 4"},{in:"2\n-1 -9",out:"\nCon lai: 0"},{in:"3\n5 5 1",out:"1 5 5\nCon lai: 3"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\n// bool laAm(int x) { ... }\nint main() {\n    int n;\n    cin >> n;\n    vector<int> v(n);\n    for (int& x : v) cin >> x;\n    // v.erase(remove_if(...), v.end());\n    // sort(...)\n    for (int x : v) cout << x << \" \";\n    cout << \"\\n\";\n    cout << \"Con lai: \" << v.size() << \"\\n\";\n    return 0;\n}",need:/remove_if[\s\S]*erase|erase\s*\(\s*remove_if/,needMsg:"Hãy dùng remove_if kết hợp erase."},{t:"Đếm số trong đoạn",d:"Nhập n rồi n số nguyên (0 ≤ a[i] ≤ 10⁶). Tiếp theo q câu hỏi, mỗi câu hai số l ≤ r: in số phần tử của dãy có giá trị trong đoạn [l, r]. Bài này được chấm cả độ hiệu quả: duyệt cả dãy cho mỗi câu hỏi (O(n·q)) sẽ quá chậm. Gợi ý: sắp xếp một lần, rồi mỗi câu hỏi dùng <code>lower_bound<\/code> và <code>upper_bound<\/code>.",tests:[{in:"6\n5 1 9 3 5 7\n3\n3 5\n6 100\n10 20",out:"3\n2\n0"},{in:"1\n4\n2\n4 4\n0 3",out:"1\n0"},{in:"5\n2 2 2 2 2\n1\n2 2",out:"5"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> a(n);\n    for (int& x : a) cin >> x;\n    // sort(...) một lần\n    int q;\n    cin >> q;\n    for (int i = 0; i < q; i++) {\n        int l, r;\n        cin >> l >> r;\n        // upper_bound(r) - lower_bound(l)\n    }\n    return 0;\n}",need:/lower_bound|upper_bound/,needMsg:"Hãy dùng lower_bound / upper_bound trên dãy đã sắp xếp.",perf:{gen:n=>{let s=n+"\n";for(let i=0;i<n;i++)s+=((i*7919)%100003)+" ";s+="\n"+n+"\n";for(let i=0;i<n;i++){const a=(i*31337)%100003,b=a+(i%500);s+=a+" "+b+"\n"}return s},ns:[300,1200,4800],need:"n",limit:n=>400*n+2000,why:"Mỗi câu hỏi duyệt cả dãy là O(n), q câu hỏi thành O(n·q). Sắp xếp một lần O(n log n), rồi mỗi câu hỏi chỉ tốn O(log n) nhờ lower_bound / upper_bound."}}]);

makeQuiz("quiz41","score41",[{"q": "<code>vector&lt;int&gt; v = {3, 1, 2};<\/code> Lệnh <code>sort(v.begin(), v.begin() + 2);<\/code> cho v là:", "o": ["1 2 3", "1 3 2", "3 1 2", "1 2 3 (cả dãy)"], "a": 1, "e": "[begin, begin + 2) chỉ gồm v[0], v[1]: 3, 1 thành 1, 3; v[2] = 2 giữ nguyên."}, {"q": "<code>find(v.begin(), v.end(), x)<\/code> trả về gì khi không có x?", "o": ["−1", "nullptr", "v.end()", "Ném lỗi"], "a": 2, "e": "Thuật toán tìm kiếm trả về last khi không thấy, nên luôn so sánh với v.end() trước khi dùng *it."}, {"q": "Sau <code>auto k = remove_if(v.begin(), v.end(), laAm);<\/code> với v có 2 số âm trong 6 số, <code>v.size()<\/code> là:", "o": ["4", "6", "2", "Tùy trình biên dịch"], "a": 1, "e": "remove_if không đổi size; phải gọi v.erase(k, v.end()) mới xóa thật."}, {"q": "Vì sao viết <code>count_if(v.begin(), v.end(), laChan)<\/code> chứ không viết <code>laChan()<\/code>?", "o": ["Hai cách như nhau", "Vì truyền chính hàm để count_if tự gọi với từng phần tử; laChan() là gọi hàm ngay (và thiếu đối số)", "Vì laChan là biến", "Vì count_if không nhận hàm"], "a": 1, "e": "Thuật toán cần “cách kiểm tra” chứ không cần một kết quả: nó sẽ gọi laChan(x) với từng x."}]);

